class Solution {
public:
    vector<int> replaceNonCoprimes(vector<int>& nums) {
        vector<int> st;
        for (int x : nums) {
            long long cur = x;
            while (!st.empty()) {
                long long g = std::gcd((long long)st.back(), cur);
                if (g > 1) {
                    cur = (st.back() * cur) / g;
                    st.pop_back();
                } else {
                    break;
                }
            }
            st.push_back((int)cur);
        }
        return st;
    }
};

class Solution {
    private long gcd(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public List<Integer> replaceNonCoprimes(int[] nums) {
        List<Integer> stack = new ArrayList<>();
        for (int num : nums) {
            long cur = num;
            while (!stack.isEmpty()) {
                long g = gcd(stack.get(stack.size() - 1), cur);
                if (g > 1) {
                    cur = (stack.remove(stack.size() - 1) * cur) / g;
                } else {
                    break;
                }
            }
            stack.add((int) cur);
        }
        return stack;
    }
}

/**
 * @param {number[]} nums
 * @return {number[]}
 */
var replaceNonCoprimes = function(nums) {
    const gcd = (a, b) => (b === 0n ? a : gcd(b, a % b));
    const stack = [];
    for (const num of nums) {
        let cur = BigInt(num);
        while (stack.length > 0) {
            const top = stack[stack.length - 1];
            const g = gcd(top, cur);
            if (g > 1n) {
                cur = (stack.pop() * cur) / g;
            } else {
                break;
            }
        }
        stack.push(cur);
    }
    return stack.map(Number);
};
